-- #######################################################################################
-- AUTOGENERATED HYPR CONFIG.
-- PLEASE USE THE CONFIG PROVIDED IN THE GIT REPO /examples/hypr.conf AND EDIT IT,
-- OR EDIT THIS ONE ACCORDING TO THE WIKI INSTRUCTIONS.
-- #######################################################################################

-- This is an example Hyprland config file.
-- Refer to the wiki for more information.
-- https://wiki.hyprland.org/Configuring/Configuring-Hyprland/

-- Please note not all available settings / options are set here.
-- For a full list, see the wiki

-- You can split this configuration into multiple files
-- Create your files separately and then link them to this file like this:
-- source = ~/.config/hypr/myColors.conf

--###############
--## MONITORS ###
--###############

-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

local monitor_1 = "DP-1, 5120x1440@240.00, auto, 1"
local monitor_1_6 = "DP-1, 5120x1440@240.00, auto, 1.25"

-- See https://wiki.hyprland.org/Configuring/Monitors/
hl.monitor({
	output = "DP-1",
	mode = "5120x1440@240",
	position = "auto",
	scale = 1.25,
})

-- monitor= , preferred, auto, 1
-- monitor= , 5120x1440@240.00, auto, 1.33

--##################
--## MY PROGRAMS ###
--##################

-- See https://wiki.hyprland.org/Configuring/Keywords/

-- Set programs that you use
local terminal = "kitty"
local fileManager = "nautilus"
local browser = "firefox"
local menu = "bash ~/.dotfiles/scripts/wofi-startup.sh mocha"
local waybar = "bash ~/.dotfiles/scripts/waybar-startup.sh"
local refreshwp = "bash ~/.dotfiles/scripts/refresh-wallpaper.sh"
local logout = "bash ~/.dotfiles/scripts/wlogout-hypr.sh"
local lock = "hyprlock"

local kill_waybar = "killall -SIGUSR1 waybar"
local goto_monitor1 = 'hyprctl keyword monitor "' .. monitor_1 .. '" && ' .. waybar --&& $refreshwp
local goto_monitor2 = 'hyprctl keyword monitor "' .. monitor_1_6 .. '" && ' .. waybar --&& $refreshwp
local goto_game_monitor = 'hyprctl keyword monitor "' .. monitor_1 .. '"&& ' .. kill_waybar --&& $refreshwp

--################
--## AUTOSTART ###
--################

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:

-- exec-once = $terminal
-- exec-once = nm-applet &
-- exec-once = blueman-applet &

-- exec-once = hypridle & hyprpaper & waybar & swaync &
-- exec-once = /usr/lib/polkit-gnome/polkit-gnome-authentication-agent-1
-- exec-once = mpd

--############################
--## ENVIRONMENT VARIABLES ###
--############################

-- See https://wiki.hyprland.org/Configuring/Environment-variables/

hl.env("XCURSOR_SIZE", "24")
hl.env("HYPRCURSOR_SIZE", "24")

hl.env("XDG_SESSION_TYPE", "wayland")
hl.env("XDG_SESSION_DESKTOP", "Hyprland")
hl.env("XDG_CURRENT_DESKTOP", "Hyprland")
hl.env("GBM_BACKEND", "nvidia-drm")
hl.env("LIBVA_DRIVER_NAME", "nvidia")
hl.env("__GLX_VENDOR_LIBRARY_NAME", "nvidia")

hl.curve("myBezier", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } })
hl.animation({
	leaf = "windows",
	enabled = true,
	speed = 7,
	bezier = "myBezier",
})
hl.animation({
	leaf = "windowsOut",
	enabled = true,
	speed = 7,
	bezier = "default",
	style = "popin 80%",
})
hl.animation({
	leaf = "border",
	enabled = true,
	speed = 10,
	bezier = "default",
})
hl.animation({
	leaf = "borderangle",
	enabled = true,
	speed = 8,
	bezier = "default",
})
hl.animation({
	leaf = "fade",
	enabled = true,
	speed = 7,
	bezier = "default",
})
hl.animation({
	leaf = "workspaces",
	enabled = true,
	speed = 6,
	bezier = "default",
})

hl.device({
	name = "epic-mouse-v1",
	sensitivity = -0.5,
})

local mainMod = "SUPER" -- Sets "Windows" key as main modifier

hl.bind(mainMod .. " + RETURN", hl.dsp.exec_cmd(terminal))
hl.bind(mainMod .. " + F", hl.dsp.exec_cmd(browser))

hl.bind(mainMod .. " + C", hl.dsp.window.close())
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + S", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + M", hl.dsp.layout("swapwithmaster master"))

hl.bind(mainMod .. " + SHIFT + P", hl.dsp.exec_cmd("hyprshot -m window"))
hl.bind(mainMod .. " + P", hl.dsp.exec_cmd("hyprshot -m region"))

hl.bind(mainMod .. " + CTRL + l", hl.dsp.exec_cmd(lock))
hl.bind(mainMod .. " + ALT + l", hl.dsp.exec_cmd(logout))

hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(waybar))
hl.bind(mainMod .. " + SHIFT + B", hl.dsp.exec_cmd(kill_waybar))
hl.bind(mainMod .. " + R", hl.dsp.exec_cmd(refreshwp))

hl.bind(mainMod .. " + SHIFT + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))

hl.bind(mainMod .. " + h", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + j", hl.dsp.focus({ direction = "down" }))
hl.bind(mainMod .. " + k", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + l", hl.dsp.focus({ direction = "right" }))

hl.bind(mainMod .. " + 1", hl.dsp.focus({ workspace = 1 }))
hl.bind(mainMod .. " + 2", hl.dsp.focus({ workspace = 2 }))
hl.bind(mainMod .. " + 3", hl.dsp.focus({ workspace = 3 }))
hl.bind(mainMod .. " + 4", hl.dsp.focus({ workspace = 4 }))
hl.bind(mainMod .. " + 5", hl.dsp.focus({ workspace = 5 }))

hl.bind(mainMod .. " + SHIFT + 1", hl.dsp.exec_cmd(goto_monitor2))
hl.bind(mainMod .. " + SHIFT + 1", hl.dsp.window.move({ workspace = 1 }))
hl.bind(mainMod .. " + SHIFT + 2", hl.dsp.exec_cmd(goto_monitor2))
hl.bind(mainMod .. " + SHIFT + 2", hl.dsp.window.move({ workspace = 2 }))
hl.bind(mainMod .. " + SHIFT + 3", hl.dsp.exec_cmd(goto_monitor2))
hl.bind(mainMod .. " + SHIFT + 3", hl.dsp.window.move({ workspace = 3 }))
hl.bind(mainMod .. " + SHIFT + 4", hl.dsp.exec_cmd(goto_monitor1))
hl.bind(mainMod .. " + SHIFT + 4", hl.dsp.window.move({ workspace = 4 }))
hl.bind(mainMod .. " + SHIFT + 5", hl.dsp.exec_cmd(goto_monitor1))
hl.bind(mainMod .. " + SHIFT + 5", hl.dsp.window.move({ workspace = 5 }))

hl.bind(mainMod .. " + 1", hl.dsp.exec_cmd(goto_monitor2))
hl.bind(mainMod .. " + 2", hl.dsp.exec_cmd(goto_monitor2))
hl.bind(mainMod .. " + 3", hl.dsp.exec_cmd(goto_monitor2))
hl.bind(mainMod .. " + 4", hl.dsp.exec_cmd(goto_game_monitor))
hl.bind(mainMod .. " + 5", hl.dsp.exec_cmd(goto_monitor1))

hl.bind(mainMod .. " + 6", hl.dsp.exec_cmd('hyprctl keyword monitor "' .. monitor_1_6 .. '" && ' .. refreshwp))
hl.bind(mainMod .. " + 7", hl.dsp.exec_cmd('hyprctl keyword monitor "' .. monitor_1 .. '" && ' .. refreshwp))

hl.bind(mainMod .. " + W", hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.window.move({ workspace = "special:magic" }))

hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

hl.bind(
	"XF86AudioRaiseVolume",
	hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%+"),
	{ locked = true, repeating = true }
)
hl.bind(
	"XF86AudioLowerVolume",
	hl.dsp.exec_cmd("wpctl set-volume @DEFAULT_AUDIO_SINK@ 5%-"),
	{ locked = true, repeating = true }
)
hl.bind(
	"XF86AudioMute",
	hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SINK@ toggle"),
	{ locked = true, repeating = true }
)
hl.bind(
	"XF86AudioMicMute",
	hl.dsp.exec_cmd("wpctl set-mute @DEFAULT_AUDIO_SOURCE@ toggle"),
	{ locked = true, repeating = true }
)
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("brightnessctl s 10%+"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("brightnessctl s 10%-"), { locked = true, repeating = true })

hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })

hl.window_rule({
	match = {
		class = "kitty",
	},
	opacity = "0.9 0.9",
})

hl.window_rule({
	match = {
		class = "org.pulseaudio.pavucontrol",
	},
	float = true,
})

hl.window_rule({
	match = {
		class = "blueman-manager",
	},
	float = true,
})

hl.window_rule({
	match = {
		class = "Slack",
	},
	workspace = "5 silent",
})

hl.window_rule({
	match = {
		class = "signal",
	},
	workspace = "5 silent",
})

hl.window_rule({
	match = {
		class = "steam",
	},
	workspace = "4 silent",
})

hl.window_rule({
	match = {
		class = ".*",
	},
	suppress_event = "maximize",
})

hl.layer_rule({
	match = { namespace = "logout_dialog" },
	blur = true,
})

hl.config({
